// Extrai dados do candidato e contexto da entrevista
const body = $input.item.json.body || $input.item.json;

// Validações
if (!body.candidato) {
  throw new Error('Dados do candidato são obrigatórios');
}

const { candidato, vaga, etapa = 'inicial' } = body;

// Constrói contexto para o agente
const contexto = [
  `Você é um entrevistador especializado em recrutamento de cuidadores.`,
  ``,
  `DADOS DO CANDIDATO:`,
  `- Nome: ${candidato.nome || 'Não informado'}`,
  `- Experiência: ${candidato.experiencia || 'Não informada'}`,
  `- Formação: ${candidato.formacao || 'Não informada'}`,
  candidato.observacoes ? `- Observações: ${candidato.observacoes}` : '',
  ``,
  vaga ? `VAGA ALVO: ${vaga.titulo || 'Vaga geral'}` : '',
  vaga?.requisitos ? `Requisitos: ${vaga.requisitos}` : '',
  ``,
  `ETAPA: ${etapa}`,
  ``,
  `Conduza uma entrevista empática, profissional e estruturada.`,
  `Faça perguntas relevantes sobre experiência, habilidades técnicas,`,
  `capacidade de lidar com situações difíceis e motivação.`,
  ``,
  `Ao final, forneça uma avaliação com pontuação de 0 a 10 nos critérios:`,
  `- Experiência técnica`,
  `- Habilidades interpessoais`,
  `- Empatia e cuidado`,
  `- Adequação à vaga`,
  `- Recomendação geral`
].filter(Boolean).join('\n');

return {
  chatInput: body.messages?.[body.messages.length - 1]?.content || body.message || '',
  systemMessage: contexto,
  candidato,
  vaga,
  etapa
};
